@import url('https://fonts.googleapis.com/css2?family=Barlow+Condensed:wght@400;500;600;700;800;900&family=DM+Mono:wght@400;500&family=Manrope:wght@400;500;600;700;800&display=swap');
:root{--ink:#080d14;--glass:rgba(9,15,23,.82);--line:rgba(216,231,246,.13);--white:#eaf1f7;--muted:#82909d;--gold:#e5b969;--cyan:#83d9ec;--red:#e36969}*{box-sizing:border-box}html,body,#game{width:100%;height:100%;margin:0;overflow:hidden;background:var(--ink);color:var(--white)}body{font-family:Manrope,Arial,sans-serif}#game{position:relative}canvas#world{position:absolute;inset:0;width:100%;height:100%;display:block}.grain{pointer-events:none;position:absolute;inset:0;opacity:.12;background-image:url("data:image/svg+xml,%3Csvg viewBox='0 0 180 180' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='.8' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)' opacity='.22'/%3E%3C/svg%3E")}.topbar{position:absolute;top:0;left:0;right:0;height:82px;padding:0 42px;display:flex;align-items:center;justify-content:space-between;background:linear-gradient(180deg,rgba(5,9,15,.9),transparent)}.brand{display:flex;align-items:center;gap:12px}.brand b{display:block;font:800 17px 'Barlow Condensed';letter-spacing:.18em}.brand small{display:block;font:9px 'DM Mono';letter-spacing:.22em;color:var(--gold);margin-top:3px}.bat-mark{font-size:26px;color:var(--gold)}.chapter{text-align:center}.chapter span,.eyebrow,.title-kicker{display:block;font:10px 'DM Mono';letter-spacing:.2em;color:var(--gold);margin-bottom:5px}.chapter b{font:600 13px 'Barlow Condensed';letter-spacing:.16em}.icon-button{border:1px solid var(--line);background:var(--glass);color:white;width:38px;height:38px;font-size:18px;cursor:pointer}.hud{position:absolute;top:102px;left:42px;right:42px;display:flex;justify-content:space-between;align-items:flex-start;pointer-events:none}.mission-card,.hero-card{background:var(--glass);border:1px solid var(--line);backdrop-filter:blur(12px);padding:16px 18px;pointer-events:auto}.mission-card{width:300px;min-height:96px}.mission-card #objective{font-size:13px;font-weight:600;line-height:1.45;max-width:260px}.progress-track{height:2px;background:#28323d;margin-top:12px}.progress-track i{display:block;height:100%;width:0;background:var(--gold);transition:width .3s}.mission-card small,.hero-card small{display:block;color:var(--muted);font:9px 'DM Mono';margin-top:6px;letter-spacing:.08em}.hero-card{display:flex;align-items:center;gap:12px;min-width:208px}.hero-avatar{width:38px;height:38px;background:#26313d;border:1px solid #536171;display:grid;place-items:center;font:700 20px 'Barlow Condensed';color:var(--gold);clip-path:polygon(15% 0,85% 0,100% 100%,0 100%)}.hero-card b{font:700 12px 'Barlow Condensed';letter-spacing:.16em}.health{width:106px;height:3px;background:#28323d;margin-top:6px}.health i{display:block;height:100%;width:100%;background:#a5cfa8;transition:width .2s}.hero-card button{margin-left:auto;background:none;border:0;color:var(--gold);font-size:21px;cursor:pointer}.hero-card button span{font:10px 'DM Mono'}.bottom-hud{position:absolute;bottom:0;left:0;right:0;padding:16px 42px;display:flex;justify-content:space-between;font:9px 'DM Mono';letter-spacing:.13em;color:#9daab6;background:linear-gradient(0deg,rgba(5,9,15,.9),transparent)}.signal{display:inline-block;width:6px;height:6px;border-radius:50%;background:#8acb9d;box-shadow:0 0 8px #8acb9d;margin-left:6px}.overlay{position:absolute;inset:0;z-index:5;display:flex;align-items:center;padding:0 9%;background:linear-gradient(90deg,rgba(4,8,14,.91) 0%,rgba(4,8,14,.67) 43%,rgba(4,8,14,.08) 100%)}.hidden{display:none!important}.title-copy{max-width:560px;margin-top:-10px}.title-kicker{font-size:11px}.title-copy h1{font:900 clamp(76px,10vw,138px)/.77 'Barlow Condensed';letter-spacing:-.03em;margin:28px 0 23px;text-shadow:0 10px 60px #000}.title-copy h1 em{font-style:normal;color:var(--gold)}.title-copy p,.pause-panel p{max-width:390px;color:#bdc7d0;font-size:14px;line-height:1.8}.primary-button{background:var(--gold);color:#111820;border:0;padding:15px 20px;font:800 12px 'Manrope';letter-spacing:.12em;margin-top:20px;cursor:pointer;transition:transform .2s,background .2s}.primary-button:hover{transform:translateY(-2px);background:#f2cb80}.primary-button span{font-size:18px;margin-left:24px}.microcopy{color:#778491;font:9px 'DM Mono';letter-spacing:.04em;margin-top:17px}.story-scrap{position:absolute;right:12%;top:30%;border-left:1px solid rgba(229,185,105,.65);padding:14px 0 14px 17px;transform:rotate(5deg);opacity:.84}.story-scrap span,.story-scrap i{display:block;font:9px 'DM Mono';letter-spacing:.16em;color:var(--gold);font-style:normal}.story-scrap b{display:block;font:700 26px/1 'Barlow Condensed';letter-spacing:.08em;margin:16px 0}.controls-hint{position:absolute;bottom:30px;left:9%;font:9px 'DM Mono';letter-spacing:.12em;color:#aab4bf}.controls-hint span{color:var(--gold);padding:0 7px}.pause-panel{max-width:520px}.pause-panel h2{font:800 clamp(40px,6vw,72px)/.94 'Barlow Condensed';margin:20px 0}.text-button{display:block;background:none;color:#b5c0ca;border:0;text-decoration:underline;padding:14px 0;cursor:pointer;font:10px 'DM Mono';letter-spacing:.1em}.toast{position:absolute;top:222px;left:50%;transform:translate(-50%,-12px);padding:10px 16px;background:rgba(7,13,20,.9);border:1px solid rgba(229,185,105,.45);font:10px 'DM Mono';letter-spacing:.09em;color:var(--gold);opacity:0;transition:.3s;pointer-events:none}.toast.show{opacity:1;transform:translate(-50%,0)}.interaction{position:absolute;bottom:15%;left:50%;transform:translateX(-50%);font:11px 'DM Mono';color:var(--gold);opacity:0;transition:opacity .2s}.interaction span{color:white;letter-spacing:.14em}.bossbar{position:absolute;bottom:12%;left:50%;transform:translateX(-50%);width:min(360px,70vw);background:var(--glass);border:1px solid var(--line);padding:12px 15px}.bossbar div{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px}.bossbar span{font:8px 'DM Mono';letter-spacing:.16em;color:var(--red)}.bossbar b{font:700 13px 'Barlow Condensed';letter-spacing:.12em}.bossbar>i{display:block;height:3px;background:#38272c}.bossbar em{display:block;height:100%;width:100%;background:var(--red);transition:width .2s}.dialogue{position:absolute;left:50%;bottom:8%;transform:translateX(-50%);width:min(660px,88vw);padding:21px 25px;background:rgba(7,12,19,.94);border:1px solid rgba(229,185,105,.4);box-shadow:0 20px 60px #0008}.speaker{font:10px 'DM Mono';letter-spacing:.19em;color:var(--gold)}.dialogue p{font-size:14px;line-height:1.7;color:#e3eaf0;margin:10px 0 15px}.dialogue button{float:right;background:none;border:0;color:var(--gold);font:10px 'DM Mono';letter-spacing:.12em;cursor:pointer}.dialogue button span{font-size:18px;margin-left:10px}.touch-controls{display:none}.mode-villain .chapter b{color:#e78686}.mode-villain .mission-card{border-color:rgba(227,105,105,.55)}
@media(max-width:700px){.topbar{height:62px;padding:0 16px}.chapter{display:none}.hud{top:72px;left:12px;right:12px}.mission-card{width:min(240px,62vw);padding:11px 12px}.eyebrow{font-size:8px}.mission-card #objective{font-size:11px}.hero-card{min-width:unset;padding:9px;gap:7px}.hero-avatar{width:31px;height:31px}.hero-card b{font-size:10px}.health{width:65px}.hero-card button{font-size:16px}.hero-card button span{display:none}.bottom-hud{padding:10px 12px;font-size:7px}.bottom-hud span:nth-child(2){display:none}.overlay{padding:0 8%}.title-copy{margin-top:-35px}.title-kicker{font-size:8px}.title-copy h1{font-size:clamp(72px,19vw,108px);margin:23px 0 16px}.title-copy p{font-size:12px;max-width:290px}.story-scrap{right:7%;top:19%;transform:scale(.7) rotate(5deg);transform-origin:top right}.controls-hint{left:8%;right:8%;bottom:105px;font-size:7px;line-height:1.8}.microcopy{font-size:7px;max-width:240px}.primary-button{padding:13px 15px;font-size:10px}.touch-controls{position:absolute;z-index:3;left:12px;right:12px;bottom:38px;display:flex;justify-content:space-between;align-items:end;pointer-events:none}.dpad,.touch-actions{pointer-events:auto}.dpad button,.touch-actions button{background:rgba(8,14,22,.72);border:1px solid rgba(235,243,250,.25);color:#f3f5f7;backdrop-filter:blur(8px);touch-action:none}.dpad>button{width:40px;height:35px;display:block;margin:auto}.dpad div{display:flex;gap:3px;margin-top:3px}.dpad div button{width:39px;height:38px}.touch-actions{display:flex;gap:6px}.touch-actions button{width:43px;height:48px;color:var(--gold);font-size:17px}.touch-actions small{display:block;font:7px 'DM Mono';color:white}.interaction{bottom:22%}.bossbar{bottom:19%}.dialogue{bottom:18%;padding:16px}.dialogue p{font-size:12px}.toast{top:190px;white-space:nowrap}}

import * as THREE from 'three';

const $=s=>document.querySelector(s), canvas=$('#world');
const scene=new THREE.Scene(); scene.background=new THREE.Color(0x101923); scene.fog=new THREE.FogExp2(0x101923,.008);
const camera=new THREE.PerspectiveCamera(54,innerWidth/innerHeight,.1,500);
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false}); renderer.setPixelRatio(Math.min(devicePixelRatio,1.7)); renderer.setSize(innerWidth,innerHeight); renderer.shadowMap.enabled=true; renderer.shadowMap.type=THREE.PCFSoftShadowMap; renderer.toneMapping=THREE.ACESFilmicToneMapping; renderer.toneMappingExposure=1.15;
scene.add(new THREE.HemisphereLight(0x9caec2,0x15141c,2));
const moon=new THREE.DirectionalLight(0x9bbbe0,2.1); moon.position.set(-35,70,25); moon.castShadow=true; moon.shadow.mapSize.set(1024,1024); scene.add(moon);
const amber=new THREE.PointLight(0xc8783c,55,75); amber.position.set(5,9,-3); scene.add(amber);
const mat=(color,rough=.8,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={road:mat(0x202832),side:mat(0x464a4d),building:[mat(0x29323d),mat(0x37414a),mat(0x242c38),mat(0x31343a)],dark:mat(0x131a23),gold:mat(0xd9aa54,.45,.35),bat:mat(0x161b23,.55,.18),cape:mat(0x111722),robin:mat(0xc53d37),blue:mat(0x1d3e62),skin:mat(0xc49b7b),window:new THREE.MeshStandardMaterial({color:0xe9b86c,emissive:0xd68130,emissiveIntensity:1.45}),bluewin:new THREE.MeshStandardMaterial({color:0x91c6e0,emissive:0x315e80,emissiveIntensity:.8}),clue:new THREE.MeshStandardMaterial({color:0x50e1ed,emissive:0x16a8cb,emissiveIntensity:2}),enemy:mat(0x55464a),enemy2:mat(0x233541),boss:mat(0x671f29),npc:mat(0x687d8b)};
const ground=new THREE.Mesh(new THREE.PlaneGeometry(260,260),mat(0x10161d));ground.rotation.x=-Math.PI/2;ground.receiveShadow=true;scene.add(ground);
const grid=new THREE.GridHelper(260,52,0x2a3640,0x202b34);grid.position.y=.018;grid.material.opacity=.3;grid.material.transparent=true;scene.add(grid);
// Streets, sidewalks, lane dashes create a readable miniature Gotham.
function box(parent,x,y,z,w,h,d,material,cast=true){const o=new THREE.Mesh(new THREE.BoxGeometry(w,h,d),material);o.position.set(x,y,z);o.castShadow=cast;o.receiveShadow=true;parent.add(o);return o}
box(scene,0,.025,0,10,.05,260,mats.road,false);box(scene,0,.025,0,260,.05,10,mats.road,false);
for(let v=-120;v<=120;v+=10){if(v===0)continue;box(scene,v,.04,0,.22,.025,260,mats.side,false);box(scene,0,.04,v,260,.025,.22,mats.side,false)}
for(let n=-120;n<=120;n+=10){if(Math.abs(n)<15)continue;box(scene,n,.061,0,.08,.015,260,mat(0x68707a),false);box(scene,0,.061,n,260,.015,.08,mat(0x68707a),false)}
for(let i=-120;i<=120;i+=10){if(Math.abs(i)<12)continue;box(scene,i,.08,0,.12,.02,3,mat(0xb7a984),false);box(scene,0,.08,i,3,.02,.12,mat(0xb7a984),false)}
// Blocks on a street grid, with lit windows and occasional rooftop shapes.
const buildings=[];
for(let x=-100;x<=100;x+=20)for(let z=-100;z<=100;z+=20){if(Math.abs(x)<12||Math.abs(z)<12)continue;const w=11+Math.random()*5,d=11+Math.random()*5,h=9+Math.random()*28, bx=x+(Math.random()-.5)*2,bz=z+(Math.random()-.5)*2;const b=box(scene,bx,h/2,bz,w,h,d,mats.building[Math.floor(Math.random()*4)]);buildings.push({x:bx,z:bz,w,d,h});box(scene,bx,h+.18,bz,w+.5,.35,d+.5,mats.dark,false);for(let yy=2.2;yy<h-1;yy+=3.4)for(let xx=-w/2+1.3;xx<w/2-.5;xx+=2.2){for(const zz of [-d/2-.012,d/2+.012]){if(Math.random()<.54){const win=new THREE.Mesh(new THREE.PlaneGeometry(.78,1.2),Math.random()<.6?mats.window:mats.bluewin);win.position.set(bx+xx,yy,bz+zz);if(zz<0)win.rotation.y=Math.PI;scene.add(win)}}}}
// distant monoliths frame the horizon
for(let i=0;i<42;i++){let a=i/42*Math.PI*2,r=106+Math.random()*24,h=20+Math.random()*52;box(scene,Math.sin(a)*r,h/2,Math.cos(a)*r,7+Math.random()*7,h,7+Math.random()*7,mats.building[i%4])}
// lamps at central intersections
for(let x=-50;x<=50;x+=20)for(let z=-50;z<=50;z+=20){if(Math.abs(x)<11&&Math.abs(z)<11)continue;const pole=mat(0x56616b,.4,.5);box(scene,x,2.2,z,.12,4.4,.12,pole);const l=new THREE.PointLight(0xe4b978,12,12,2);l.position.set(x,4.2,z);scene.add(l);const bulb=new THREE.Mesh(new THREE.SphereGeometry(.12,8,6),mats.window);bulb.position.copy(l.position);scene.add(bulb)}

const actors=[];let activeName='BATMAN',player,companion,mode='story',gameStarted=false,paused=false,dialogueLock=false,stealth=false,health=100,clues=0,gangDown=0,storyStage=0,boss=null,selectedVillain=0,interactionTarget=null,toastTimer=0,clock=new THREE.Clock();
const villainNames=['THE JOKER','THE PENGUIN','POISON IVY','MR. FREEZE','MAD HATTER','KILLER CROC','BANE','TWO-FACE','RED HOOD','THE RIDDLER'];
const villainStyles=[0xd94945,0x6a8c9d,0x47754f,0x7bbbd0,0x6f587f,0x526557,0xb37c55,0x74747a,0x9b3736,0x63b78e];
function makeFigure(kind='batman',color,scale=1){const g=new THREE.Group(), suit=kind==='robin'?mats.robin:kind==='villain'?mat(color||0x773b40):mats.bat, body= new THREE.Mesh(new THREE.CapsuleGeometry(.43,.88,4,8),suit);body.position.y=1.22;body.castShadow=true;g.add(body);const head=new THREE.Mesh(new THREE.SphereGeometry(.34,12,10),kind==='villain'?mat(0xc49b7b):suit);head.position.y=2.08;head.castShadow=true;g.add(head);if(kind!=='villain'){const ears=new THREE.Mesh(new THREE.ConeGeometry(.12,.48,5),suit);ears.position.set(-.2,2.48,0);ears.rotation.z=-.1;g.add(ears);const e2=ears.clone();e2.position.x=.2;g.add(e2)}const cape=new THREE.Mesh(new THREE.ConeGeometry(.7,1.8,5,1,true),kind==='robin'?mats.blue:mats.cape);cape.position.set(0,1.15,-.34);cape.rotation.x=-.14;cape.castShadow=true;g.add(cape);const belt=box(g,0,.86,0,.8,.14,.52,mats.gold,false);belt.position.y=.9;const armL=box(g,-.55,1.18,0,.2,.7,.22,suit);const armR=box(g,.55,1.18,0,.2,.7,.22,suit);const legL=box(g,-.22,.42,0,.26,.7,.3,suit);const legR=box(g,.22,.42,0,.26,.7,.3,suit);g.scale.setScalar(scale);g.userData={kind,armL,armR,legL,legR,cape,body,walk:0};return g}
player=makeFigure();player.position.set(0,0,0);scene.add(player);
companion=makeFigure('robin',null,.84);companion.position.set(-1.7,0,1.8);scene.add(companion);
function addNpc(name,x,z,kind='person',color=0x638091,lines=[]){const g=kind==='villain'?makeFigure('villain',color):makeFigure('person');if(kind==='person'){g.children[0].material=mat(color);g.children[1].material=mats.skin;g.children[2].material=mat(color)}g.position.set(x,0,z);scene.add(g);const label=makeLabel(name);label.position.set(0,3.2,0);g.add(label);actors.push({mesh:g,name,kind,health:kind==='villain'?90:0,max:kind==='villain'?90:0,alive:true,lines,alert:false,range:kind==='villain'?12:0,baseColor:color});return g}
function makeLabel(text){const c=document.createElement('canvas');c.width=256;c.height=64;const ctx=c.getContext('2d');ctx.fillStyle='rgba(6,12,18,.8)';ctx.fillRect(0,14,256,38);ctx.fillStyle='#e7c47e';ctx.font='bold 22px monospace';ctx.textAlign='center';ctx.fillText(text,128,40);const t=new THREE.CanvasTexture(c);const m=new THREE.Sprite(new THREE.SpriteMaterial({map:t,transparent:true}));m.scale.set(3.2,.8,1);return m}
const selina=addNpc('SELINA KYLE',8,3,'person',0x542a37,['CATWOMAN: Gotham has a new riddle. The gangs are moving evidence through the old theater district.','CATWOMAN: I saw a green calling card near the docks. Try not to make a mess, Bat.']);
const harvey=addNpc('HARVEY DENT',-7,-3,'person',0x786c54,['HARVEY DENT: I used to believe one good day could save a city. Then one day changed everything.','HARVEY DENT: The gang lieutenant is hiding near the courthouse. Bring me proof, and I can make the charges stick.']);
const alfred=addNpc('ALFRED',2,5,'person',0x66707c,['ALFRED: The cave is ready, sir. The new suit, the car, and a rather substantial first-aid kit are all accounted for.','ALFRED: And the young Mr. Grayson is quite determined. I have made him a suit. Please do try to keep him out of trouble.']);
const villains=[]; const villainSpots=[[42,5],[-40,-22],[34,42],[-45,42],[12,-54],[54,-42],[-59,3],[48,-1],[-12,62],[25,-28]];
for(let i=0;i<villainNames.length;i++){const [x,z]=villainSpots[i];const a=addNpc(villainNames[i],x,z,'villain',villainStyles[i]);villains.push(actors[actors.length-1]);}
// Crime crews: a readable group of patrolling foes with health and combat feedback.
const enemies=[];
for(let i=0;i<17;i++){const x=(Math.random()-.5)*112,z=(Math.random()-.5)*112;if(Math.abs(x)<8&&Math.abs(z)<8){i--;continue}const g=makeFigure('villain',i%3===0?0x543b36:0x32424e,.88);g.position.set(x,0,z);scene.add(g);const e={mesh:g,name:i<8?'GANG LOOKOUT':'MOB ENFORCER',kind:'enemy',health:34,max:34,alive:true,alert:false,range:9,home:new THREE.Vector3(x,0,z)};actors.push(e);enemies.push(e)}
// Riddler's evidence: 40 distinctive glowing objects scattered across reachable blocks.
const evidence=[];
for(let i=0;i<40;i++){let x,z,tries=0;do{x=(Math.random()-.5)*105;z=(Math.random()-.5)*105;tries++}while(tries<50&&((Math.abs(x)<9&&Math.abs(z)<9)||buildings.some(b=>Math.abs(x-b.x)<b.w/2+1&&Math.abs(z-b.z)<b.d/2+1)));const g=new THREE.Group();const orb=new THREE.Mesh(new THREE.OctahedronGeometry(.42,0),mats.clue);orb.position.y=.8;g.add(orb);const ring=new THREE.Mesh(new THREE.TorusGeometry(.7,.035,6,20),new THREE.MeshBasicMaterial({color:0x51dff2}));ring.rotation.x=Math.PI/2;ring.position.y=.8;g.add(ring);g.position.set(x,0,z);scene.add(g);evidence.push({mesh:g,found:false,id:i+1})}
// Neighborhood beacons mark the changing case objectives.
const markers=[];function addMarker(name,x,z,color=0xe5b969){const g=new THREE.Group();const ring=new THREE.Mesh(new THREE.TorusGeometry(1.05,.07,8,32),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.85}));ring.rotation.x=Math.PI/2;ring.position.y=.1;g.add(ring);const beam=new THREE.Mesh(new THREE.CylinderGeometry(.04,.5,9,12,1,true),new THREE.MeshBasicMaterial({color,transparent:true,opacity:.14,depthWrite:false}));beam.position.y=4.5;g.add(beam);g.position.set(x,0,z);scene.add(g);markers.push({mesh:g,name,x,z,active:false})}
addMarker('GANG DISTRICT',17,12,0xe5b969);addMarker('CASE CLUES',-16,16,0x58d8eb);addMarker('RIDDLER',24,-28,0x58d8eb);addMarker('TWO-FACE',-12,-36,0xe36969);
// Batmobile and Robin's bike are explorable ride pickups, not just menu art.
function makeCar(x,z){const g=new THREE.Group();box(g,0,.65,0,3.5,.65,6,mats.dark);box(g,0,1.05,-.3,2.6,.65,2.7,mat(0x293847,.25,.6));for(const xx of [-1.25,1.25])for(const zz of [-1.9,1.9]){const wheel=new THREE.Mesh(new THREE.CylinderGeometry(.53,.53,.35,12),mat(0x101318));wheel.rotation.z=Math.PI/2;wheel.position.set(xx,.42,zz);g.add(wheel)}const lights=new THREE.Mesh(new THREE.BoxGeometry(1.9,.18,.1),new THREE.MeshBasicMaterial({color:0x73cbe5}));lights.position.set(0,.82,3.04);g.add(lights);g.position.set(x,0,z);scene.add(g);return g}
const batmobile=makeCar(5,-3);const bike=new THREE.Group();const frame=box(bike,0,.9,0,.4,.42,2,mats.robin);for(const zz of [-.9,.9]){const wh=new THREE.Mesh(new THREE.TorusGeometry(.48,.1,7,18),mat(0x15191e));wh.rotation.y=Math.PI/2;wh.position.set(0,.5,zz);bike.add(wh)}bike.position.set(-4,0,4);scene.add(bike);

const introLines=[
['GOTHAM · 1982','A winter night. Bruce Wayne walks home from the cinema between his parents. In a narrow alley, a desperate gunman demands their money. Thomas Wayne gives him the two hundred dollars in his coat pocket. A flash, a cry—and Bruce is left alone beneath the city lights.'],
['GOTHAM · 26 YEARS LATER','The fortune from that coat pocket became a billion-dollar beginning. Bruce rebuilt the old Wayne estate and renamed it Wayne Enterprises. He filled its halls with friends—and with Harvey Dent, Gotham’s bright new hope.'],
['ONE YEAR LATER','A terrible attack leaves Harvey’s face scarred and his faith in justice broken. Bruce disappears from the parties. He finds an old cave beneath the estate, and begins building something the city has never seen.'],
