const batmobile=car(5,-3),bike=car(-4,4,true);
const intro=[['GOTHAM · 1982','A winter night. Bruce Wayne walks home from the cinema with his parents. An old gunman demands their money. Thomas gives him the two hundred dollars in his coat pocket. A flash, a cry—and Bruce is left alone beneath the city lights.'],['GOTHAM · 26 YEARS LATER','The fortune from that coat pocket becomes a billion-dollar beginning. Bruce rebuilds the old Wayne estate and names it Wayne Enterprises. He fills its halls with friends—and with Harvey Dent, Gotham’s bright new hope.'],['ONE YEAR LATER','A terrible attack scars Harvey’s face and breaks his faith in justice. Bruce disappears from the parties. Beneath the estate, he finds an old cave.'],['THE CAVE','“Excuse me, sir. Looking for something? This cave is old—even I am old.” “I’m trying to do something with this place. What makes you think you can tell me what to do?” “I understand standing your ground. But you are trespassing.” Bruce refuses. The old man leaves him to the dark.'],['THREE MONTHS LATER','“Excuse me, sir. Remember me? I’m Alfred.” “What are you doing here?” “Trying to help you make this cave.” Months of work bring an elevator, a suit machine, a fast black car, batarangs, smoke pellets, and a grapple gun. Alfred supplies a self-defense book; Bruce supplies the bruises.'],['THE PARTNERS','Several months later, the cowl fits. A determined young man tumbles into the cave: “I’m Dick Grayson. Robin. I’m over seventeen—and I can fight crime.” Alfred makes a second suit, wing-shaped discs, a grapple, a staff, and a red-striped motorcycle. Gotham gets two shadows.'],['GOTHAM · NOW','Street crews. A mob operation. Forty riddles. Selina Kyle, Harvey Dent, and a city full of people worth saving. The case starts here.']];
let mode='story',gameStarted=false,paused=false,dialogueLock=false,queue=[],afterTalk=null,storyStage=0,gangDown=0,clues=0,boss=null,selected=0,health=100,heroHealth=100,stealth=false,glide=false,ride=null,toastTimer=0,attackTimer=0,damageTimer=0,gameTime=0,cameraYaw=0,cameraPitch=.2,mouse=null,keys={},target=null,clock=new THREE.Clock();
function toast(t){$('#toast').textContent=t;$('#toast').classList.add('show');toastTimer=2.6}
function setObjective(text,chapter,pct=0,total=8,labelText){$('#objective').textContent=text;$('#chapter-name').textContent=chapter;$('#progress-fill').style.width=`${Math.max(0,Math.min(100,pct/total*100))}%`;$('#progress-label').textContent=labelText||`${pct} / ${total} case clues`}
function updateObjective(){if(mode==='villain'){setObjective('Defeat Batman and Robin. Swap villains with Q.','VILLAIN RAMPAGE · '+villains[selected],100-heroHealth,100,`HERO VITALS ${heroHealth}%`);return}if(storyStage===0)setObjective(`Stop the gang operation. ${Math.max(0,5-gangDown)} crew members remain.`,'THE STREET WAR',gangDown,5,`${gangDown} / 5 crew stopped`);if(storyStage===1)setObjective('Search Gotham for the Riddler’s evidence. Look for cyan glows.','A TRAIL OF RIDDLES',clues,8,`${clues} / 8 key clues · ${clues} / 40 total`);if(storyStage===2)setObjective('Confront the Riddler at his hideout. Watch his tells.','THE RIDDLER',boss?.health??100,100,`RIDDLER · ${Math.ceil(boss?.health??100)}%`);if(storyStage===3)setObjective('Face Harvey Dent before the city loses him completely.','THE DARK SIDE OF JUSTICE',boss?.health??100,100,`TWO-FACE · ${Math.ceil(boss?.health??100)}%`);if(storyStage>=4)setObjective('Gotham is safe tonight. The case is yours to replay.','CASE FILE CLOSED',1,1,'CITY STATUS: HOLDING')}
function showLine(){if(!queue.length){$('#dialogue').classList.add('hidden');dialogueLock=false;const f=afterTalk;afterTalk=null;if(f)f();return}const [who,text]=queue.shift();$('#speaker').textContent=who;$('#dialogue-text').textContent=text;$('#dialogue').classList.remove('hidden')}
function talk(lines,done){queue=lines.slice();afterTalk=done||null;dialogueLock=true;showLine()}
$('#dialogue-next').onclick=showLine;$('#start-button').onclick=()=>{$('#start-screen').classList.add('hidden');gameStarted=true;talk(intro,()=>{updateObjective();toast('CASE 001 OPEN — GOTHAM NEEDS YOU')})};
function activate(name){markers.forEach(m=>m.active=m.name===name)}
function progress(){if(mode!=='story')return;if(storyStage===0&&gangDown>=5){storyStage=1;activate('CASE CLUES');talk([['ROBIN','That was the street crew. Their boss left a trail—forty riddles, if reports are right. Eight should lead us to him.'],['ALFRED','I have marked the likely search area on your display.']],updateObjective)}else if(storyStage===1&&clues>=8){storyStage=2;boss=actors.find(a=>a.name==='THE RIDDLER');boss.health=100;boss.alive=true;boss.mesh.visible=true;boss.alert=true;activate('RIDDLER');talk([['THE RIDDLER','Eight little answers, and you think you know the question? Come find me. Try to keep up.']],updateObjective)}else if(storyStage===2&&boss===actors.find(a=>a.name==='THE RIDDLER')&&boss.health<=0){storyStage=3;boss=actors.find(a=>a.name==='TWO-FACE');boss.health=100;boss.alive=true;boss.mesh.visible=true;boss.alert=true;activate('TWO-FACE');talk([['HARVEY DENT','You should have left me out of this, Bruce. Gotham makes its own choices now.'],['ROBIN','We can still reach him. Together.']],updateObjective)}else if(storyStage===3&&boss?.health<=0){storyStage=4;boss=null;activate('');$('#bossbar').classList.add('hidden');$('#ending-title').textContent='GOTHAM STILL STANDS.';$('#ending-copy').textContent=`The city made it through the night. You recovered ${clues} of 40 evidence pieces and stopped a friend from falling into darkness.`;$('#ending-screen').classList.remove('hidden');paused=true;updateObjective()}}
function swap(){if(mode==='villain'){selected=(selected+1)%villains.length;const color=mat(colors[selected]);player.children[0].material=color;player.children[1].material=color;$('#hero-name').textContent=villains[selected];$('#hero-avatar').textContent=villains[selected][0];$('#boss-name').textContent='BATMAN & ROBIN';toast('PLAYING AS '+villains[selected]);updateObjective();return}player=player===bat?robin:bat;companion=player===bat?robin:bat;$('#hero-name').textContent=player===bat?'THE BAT':'THE BOY WONDER';$('#hero-avatar').textContent=player===bat?'B':'R';toast('CONTROL: '+(player===bat?'BATMAN':'ROBIN'))}
$('#swap-button').onclick=swap;
function villainMode(){mode='villain';document.body.classList.add('mode-villain');$('#ending-screen').classList.add('hidden');paused=false;gameStarted=true;player=bat;companion=robin;selected=0;player.position.set(45,0,5);player.children[0].material=mat(colors[0]);player.children[1].material=mat(colors[0]);robin.visible=false;heroHealth=100;setObjective('Defeat Batman and Robin. Swap villains with Q.','VILLAIN RAMPAGE · '+villains[0],0,100,'HERO VITALS 100%');$('#boss-name').textContent='BATMAN & ROBIN';$('#bossbar').classList.remove('hidden');toast('VILLAIN MODE · Q TO CHANGE YOUR VILLAIN')}
$('#replay-button').onclick=villainMode;$('#new-case-button').onclick=()=>location.reload();
function pause(){if(!gameStarted)return;paused=!paused;$('#pause-screen').classList.toggle('hidden',!paused)}$('#pause-button').onclick=pause;$('#resume-button').onclick=pause;

