// The city simulation: readable third-person movement, compact combat, and investigation.
const clock3=new THREE.Clock();
const moveSpeed=8, keysDown=new Set(), ray=new THREE.Raycaster();
let nearby=null, pointerDown=null, grapplePoint=null, grappleTime=0, attackCooldown=0, hitFlash=0, companionTick=0;
const villainTargets=[];
actors.filter(a=>a.type==='villain').forEach(a=>{a.mesh.visible=false;a.alive=false});
function setHealth(){const val=mode==='villain'?heroHealth:health;$('#health-fill').style.width=`${Math.max(0,val)}%`;$('#health-label').textContent=`VITALS ${Math.ceil(Math.max(0,val))}%`;$('#health-fill').style.background=val<30?'#e36969':''}
function showBoss(){if(mode==='villain'||(boss&&storyStage>=2&&storyStage<=3)){$('#bossbar').classList.remove('hidden');const h=mode==='villain'?heroHealth:boss.health;$('#boss-fill').style.width=`${Math.max(0,h)}%`}else $('#bossbar').classList.add('hidden')}
function distance(a,b){return Math.hypot(a.x-b.x,a.z-b.z)}
function nearestActor(max=3){let best=null,bd=max;for(const a of actors){if(!a.alive||!a.mesh.visible||a.type==='enemy'||a.type==='villain')continue;const d=distance(player.position,a.mesh.position);if(d<bd){best=a;bd=d}}return best}
function nearbyRide(max=4){for(const v of [batmobile,bike])if(v!==ride&&v.visible&&Math.hypot(player.position.x-v.position.x,player.position.z-v.position.z)<max)return v;return null}
function addHealth(delta){if(mode==='villain')heroHealth=Math.min(100,heroHealth+delta);else health=Math.min(100,health+delta);setHealth()}
function collect(){let got=false;for(const e of evidence){if(!e.found&&Math.hypot(player.position.x-e.mesh.position.x,player.position.z-e.mesh.position.z)<1.65){e.found=true;e.mesh.visible=false;clues++;got=true;$('#collectible-label').textContent=`RIDDLE EVIDENCE ${String(clues).padStart(2,'0')} / 40`;toast(`EVIDENCE ${String(clues).padStart(2,'0')} / 40 RECOVERED`);break}}if(got){updateObjective();progress()}}
function interact(){if(dialogueLock||!gameStarted)return;const actorNear=nearestActor(3.2);if(actorNear&&actorNear.lines?.length){talk(actorNear.lines,()=>{if(actorNear.name==='SELINA KYLE')activate('CASE CLUES');updateObjective()});return}const v=nearbyRide(4);if(v){if(ride===v){ride=null;player.visible=true;player.position.copy(v.position).add(new THREE.Vector3(2,0,0));toast('EXITED VEHICLE')}else{ride=v;player.visible=false;toast(v===batmobile?'BATMOBILE · BOOST READY':'RED STRIPE · READY')};return}if(mode==='story'&&storyStage===1){const clue=evidence.find(e=>!e.found);if(clue)toast('SCAN THE CYAN RIDDLE GLOWS TO COLLECT EVIDENCE');return}toast('NOTHING TO INTERACT WITH HERE')}
function forward(){return new THREE.Vector3(Math.sin(cameraYaw),0,Math.cos(cameraYaw))}
function strike(){if(!gameStarted||paused||dialogueLock||attackCooldown>0)return;attackCooldown=.42;const origin=player.position,dir=forward();let candidates=mode==='villain'?villainTargets.filter(a=>a.alive):enemies.filter(a=>a.alive);if(mode==='story'&&boss&&storyStage>=2&&boss.alive)candidates=[boss];let victim=null,best=3.25;for(const a of candidates){const dx=a.mesh.position.x-origin.x,dz=a.mesh.position.z-origin.z,d=Math.hypot(dx,dz),dot=d?((dx*dir.x+dz*dir.z)/d):1;if(d<best&&(dot>.15||d<1.3)){victim=a;best=d}}if(victim){const damage=stealth?28:18;victim.health-=damage;victim.alert=true;victim.mesh.rotation.y=Math.atan2(origin.x-victim.mesh.position.x,origin.z-victim.mesh.position.z);toast(stealth?'SILENT TAKEDOWN':'STRIKE · '+victim.name);if(victim.health<=0){victim.health=0;victim.alive=false;victim.mesh.visible=false;if(victim.type==='enemy'){gangDown++;if(gangDown===5)toast('GANG OPERATION DISRUPTED');progress()}if(mode==='villain'){toast('HERO DOWN');if(villainTargets.every(a=>!a.alive)){villainTargets.forEach(a=>{a.alive=true;a.health=100;a.mesh.visible=true});heroHealth=100;toast('HEROES RALLY — FIGHT ON')}}if(victim===boss)progress()}else if(victim===boss){$('#boss-fill').style.width=`${victim.health}%`;updateObjective()}}else if(mode==='story'){toast('NO THREAT IN RANGE')} }
function damageHero(amount){if(mode==='villain')heroHealth=Math.max(0,heroHealth-amount);else health=Math.max(0,health-amount);setHealth();if((mode==='villain'?heroHealth:health)<=0){if(mode==='villain'){heroHealth=100;player.position.set(45,0,5);toast('THE HEROES PUSH YOU BACK')}else{health=100;player.position.set(0,0,0);toast('ALFRED: BACK TO THE CAVE. TAKE A BREATHER.')}}}
function enemiesThink(dt){const now=gameTime;for(const e of [...enemies,...villainTargets]){if(!e.alive||!e.mesh.visible)continue;const d=distance(e.mesh.position,player.position);const hidden=stealth&&mode!=='villain';if(d<13&&!hidden)e.alert=true;if(e.alert&&d>2.05){const dx=player.position.x-e.mesh.position.x,dz=player.position.z-e.mesh.position.z,len=Math.hypot(dx,dz)||1;e.mesh.position.x+=dx/len*dt*(mode==='villain'?2.4:2.1);e.mesh.position.z+=dz/len*dt*(mode==='villain'?2.4:2.1);e.mesh.rotation.y=Math.atan2(dx,dz)}else if(e.alert&&d<=2.05&&now-(e.lastHit||0)>1.05){e.lastHit=now;damageHero(mode==='villain'?10:8)}}}
function moveCompanion(dt){if(!companion?.visible||ride)return;const d=distance(companion.position,player.position);if(d>4){const dx=player.position.x-companion.position.x,dz=player.position.z-companion.position.z;companion.position.x+=dx/(d||1)*dt*7;companion.position.z+=dz/(d||1)*dt*7;companion.rotation.y=Math.atan2(dx,dz)}}
function blocked(x,z){for(const b of buildings)if(Math.abs(x-b.x)<b.w/2+.55&&Math.abs(z-b.z)<b.d/2+.55)return true;return false}
function move(dt){const f=forward(),right=new THREE.Vector3(f.z,0,-f.x);let mx=0,mz=0;if(keysDown.has('w')||keysDown.has('arrowup')){mx+=f.x;mz+=f.z}if(keysDown.has('s')||keysDown.has('arrowdown')){mx-=f.x;mz-=f.z}if(keysDown.has('a')||keysDown.has('arrowleft')){mx-=right.x;mz-=right.z}if(keysDown.has('d')||keysDown.has('arrowright')){mx+=right.x;mz+=right.z}const len=Math.hypot(mx,mz);if(len){const speed=ride?15:(glide?12:(stealth?3.5:moveSpeed));mx=mx/len*speed*dt;mz=mz/len*speed*dt;const pos=ride?ride.position:player.position;const nx=THREE.MathUtils.clamp(pos.x+mx,-119,119),nz=THREE.MathUtils.clamp(pos.z+mz,-119,119);if(!blocked(nx,pos.z))pos.x=nx;if(!blocked(pos.x,nz))pos.z=nz;if(!ride){player.rotation.y=Math.atan2(mx,mz);player.userData.walk+=dt*12;for(const limb of [player.userData.l,player.userData.r])limb.rotation.x=Math.sin(player.userData.walk)*(stealth?.18:.55);for(const limb of [player.userData.ll,player.userData.rr])limb.rotation.x=Math.sin(player.userData.walk+Math.PI)*(stealth?.18:.55)}}if(glide&&keysDown.has('w'))player.position.y=THREE.MathUtils.lerp(player.position.y,1.1,.08);else player.position.y=THREE.MathUtils.lerp(player.position.y,0,.1)}
function useGrapple(){const dir=forward(),p=player.position;grapplePoint=new THREE.Vector3(p.x+dir.x*14,0,p.z+dir.z*14);grappleTime=.55;toast('GRAPPLE LINE FIRED')}
function toggleGlide(){if(ride)return;glide=!glide;toast(glide?'CAPE GLIDE · HOLD W TO SOAR':'CAPE FOLDED')}
function setStealth(on){stealth=on;player.traverse(o=>{if(o.isMesh&&o.material?.emissive)o.material.emissive.setHex(on?0x101c27:0x000000)})}
function doAction(a){if(a==='attack')strike();if(a==='interact')interact();if(a==='swap')swap();if(a==='stealth')setStealth(!stealth);if(a==='glide')toggleGlide();if(a==='grapple')useGrapple()}
window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if([' ','arrowup','arrowdown','arrowleft','arrowright'].includes(k))e.preventDefault();keysDown.add(k);if(k==='q'&&!e.repeat)swap();if(k==='e'&&!e.repeat)interact();if(k===' '&&!e.repeat)strike();if(k==='f'&&!e.repeat)useGrapple();if(k==='g'&&!e.repeat)toggleGlide();if(k==='shift')setStealth(true);if(k==='escape'&&!e.repeat)pause()});window.addEventListener('keyup',e=>{const k=e.key.toLowerCase();keysDown.delete(k);if(k==='shift')setStealth(false)});
canvas.addEventListener('pointerdown',e=>{if(!gameStarted||paused)return;pointerDown={x:e.clientX,y:e.clientY};canvas.setPointerCapture?.(e.pointerId)});canvas.addEventListener('pointerup',e=>{if(pointerDown&&Math.hypot(e.clientX-pointerDown.x,e.clientY-pointerDown.y)<8)strike();pointerDown=null});canvas.addEventListener('pointermove',e=>{if(pointerDown){cameraYaw-=(e.clientX-pointerDown.x)*.006;cameraPitch=THREE.MathUtils.clamp(cameraPitch+(e.clientY-pointerDown.y)*.003,-.1,.75);pointerDown={x:e.clientX,y:e.clientY}}});
document.querySelectorAll('[data-key]').forEach(b=>{const k=b.dataset.key;b.addEventListener('pointerdown',e=>{e.preventDefault();keysDown.add(k);b.setPointerCapture(e.pointerId)});for(const ev of ['pointerup','pointercancel','lostpointercapture'])b.addEventListener(ev,()=>keysDown.delete(k))});document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('pointerdown',e=>{e.preventDefault();doAction(b.dataset.action)}));
function updateInteraction(){let text='';if(nearestActor(3.2))text='[ E ]  TALK';else if(nearbyRide(4))text='[ E ]  '+(ride?'EXIT VEHICLE':'ENTER VEHICLE');else if(evidence.some(e=>!e.found&&Math.hypot(player.position.x-e.mesh.position.x,player.position.z-e.mesh.position.z)<2))text='[ E ]  SCAN EVIDENCE';$('#interaction').textContent=text;$('#interaction').classList.toggle('show',!!text)}
function cameraUpdate(dt){const focus=ride?ride.position:player.position;const dist=ride?13:9.5;const desired=new THREE.Vector3(focus.x-Math.sin(cameraYaw)*dist,focus.y+3+cameraPitch*5,focus.z-Math.cos(cameraYaw)*dist);camera.position.lerp(desired,1-Math.exp(-dt*5));camera.lookAt(focus.x,focus.y+1.25,focus.z+1);}
function animate(){requestAnimationFrame(animate);const dt=Math.min(clock3.getDelta(),.04);if(gameStarted&&!paused){gameTime+=dt;if(!dialogueLock){move(dt);if(grappleTime>0){const d=player.position.distanceTo(grapplePoint);player.position.lerp(grapplePoint,Math.min(1,dt*3));grappleTime-=dt;if(d<1)grappleTime=0}moveCompanion(dt);enemiesThink(dt);collect();updateInteraction();attackCooldown=Math.max(0,attackCooldown-dt);if(toastTimer>0){toastTimer-=dt;if(toastTimer<=0)$('#toast').classList.remove('show')}for(const e of evidence)if(!e.found){e.mesh.rotation.y+=dt*.7;e.mesh.position.y=.12+Math.sin(gameTime*2+e.id)*.12}for(const m of markers){m.mesh.rotation.y+=dt*.35;m.mesh.visible=m.active||m.name==='GANG DISTRICT'&&storyStage===0}}}cameraUpdate(dt);showBoss();renderer.render(scene,camera)}
window.addEventListener('resize',()=>{camera.aspect=innerWidth/innerHeight;camera.updateProjectionMatrix();renderer.setSize(innerWidth,innerHeight);renderer.setPixelRatio(Math.min(devicePixelRatio,1.6))});
