import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
const base=process.env.HOME+'/.local/share/omgithub-playwright';
const require=createRequire(base+'/package.json');
const {chromium}=require('playwright');
const config=JSON.parse(readFileSync(base+'/linux.json','utf8'));
process.env.DISPLAY ||= ':'+readFileSync(base+'/display','utf8').trim();
const browser=await chromium.launch({...config.browser.launchOptions});
const page=await browser.newPage({viewport:{width:1200,height:800},deviceScaleFactor:1});
const errors=[];page.on('pageerror',e=>errors.push('PAGE '+e.message));page.on('console',m=>{if(m.type()==='error')errors.push('CONSOLE '+m.text())});page.on('requestfailed',r=>errors.push('REQUEST '+r.url()+' '+r.failure()?.errorText));
await page.goto('http://127.0.0.1:3000/',{waitUntil:'networkidle',timeout:60000});
console.log('title',await page.title(),'canvas',await page.locator('#world').count());
await page.locator('#start-button').click();
for(let i=0;i<20;i++){await page.waitForTimeout(100); if(await page.locator('#dialogue').evaluate(el=>el.classList.contains('hidden')))break; await page.locator('#dialogue-next').click();}
await page.waitForTimeout(3000);
console.log('objective',await page.locator('#objective').innerText(),'dialogueHidden',await page.locator('#dialogue').evaluate(el=>el.classList.contains('hidden')),'canvas',await page.locator('#world').evaluate(c=>[c.width,c.height]));
mkdirSync('/tmp/opencode',{recursive:true});await page.screenshot({path:'/tmp/opencode/gotham.jpg',type:'jpeg',quality:75});
console.log('errors',errors.slice(0,20));
await browser.close();
