import {createRequire} from 'node:module';import{readFileSync,mkdirSync}from'node:fs';const b=process.env.HOME+'/.local/share/omgithub-playwright',r=createRequire(b+'/package.json'),{chromium}=r('playwright'),cfg=JSON.parse(readFileSync(b+'/linux.json','utf8'));process.env.DISPLAY||=':'+readFileSync(b+'/display','utf8').trim();const browser=await chromium.launch({...cfg.browser.launchOptions}),page=await browser.newPage({viewport:{width:1200,height:800}}),errors=[];page.on('pageerror',e=>errors.push(e.message));page.on('console',m=>{if(m.type()==='error')errors.push(m.text())});await page.route('**/game.js',async route=>{const res=await route.fetch(),src=await res.text();await route.fulfill({response:res,body:src+'\nwindow.__qa={state:()=>({storyStage,gangDown,clues,mode,health,heroHealth}),actors,enemies,evidence,progress,collect,villainMode,swap,player};'});});await page.goto('http://127.0.0.1:3000/',{waitUntil:'networkidle'});await page.locator('#start-button').click();for(let i=0;i<30;i++){if(await page.locator('#dialogue').evaluate(e=>e.classList.contains('hidden')))break;await page.locator('#dialogue-next').click()}
await page.evaluate(()=>{const q=window.__qa;q.gangDown=5;q.progress()});let s1=await page.locator('#objective').innerText();for(let i=0;i<10;i++){if(await page.locator('#dialogue').evaluate(e=>e.classList.contains('hidden')))break;await page.locator('#dialogue-next').click()}await page.evaluate(()=>{const q=window.__qa;for(let i=0;i<8;i++){const e=q.evidence.find(x=>!x.found);e.mesh.position.copy(q.player.position);q.collect()}});for(let i=0;i<10;i++){if(await page.locator('#dialogue').evaluate(e=>e.classList.contains('hidden')))break;await page.locator('#dialogue-next').click()};let riddler=await page.evaluate(()=>window.__qa.state());await page.evaluate(()=>{const q=window.__qa;let a=q.actors.find(x=>x.name==='THE RIDDLER');a.health=0;q.progress()});for(let i=0;i<10;i++){if(await page.locator('#dialogue').evaluate(e=>e.classList.contains('hidden')))break;await page.locator('#dialogue-next').click()};let twoface=await page.evaluate(()=>window.__qa.state());await page.evaluate(()=>{let a=window.__qa.actors.find(x=>x.name==='TWO-FACE');a.health=0;window.__qa.progress()});let ending=await page.locator('#ending-screen').evaluate(e=>!e.classList.contains('hidden'));await page.locator('#replay-button').click();await page.keyboard.press('q');let replay={hero:await page.locator('#hero-name').innerText(),objective:await page.locator('#objective').innerText()};await page.screenshot({path:'/tmp/opencode/gotham-latest.jpg',type:'jpeg',quality:70});console.log(JSON.stringify({s1,riddler,twoface,ending,replay,errors},null,2));await browser.close();
